    #[test]
    fn every_registered_id_has_a_root_module() {
        let listed = modules();
        for (id, info_id) in &listed {
            assert_eq!(id, info_id, "module INFO names a different algorithm");
        }
        let mut registered: Vec<&str> = nextssl_registry::all().iter().map(|a| a.id).collect();
        let mut have: Vec<&str> = listed.iter().map(|(id, _)| *id).collect();
        registered.sort_unstable();
        have.sort_unstable();
        assert_eq!(
            registered, have,
            "registry and generated root modules differ"
        );
    }
